import sys, json
d = json.load(sys.stdin)
hooks = d.get('hooks', {})
for event, groups in hooks.items():
    for group in groups:
        matcher = group.get('matcher', '*')
        for h in group.get('hooks', []):
            cmd = h.get('command', 'N/A')
            if 'entire' in cmd.lower():
                print(f'{event} [{matcher}]: {cmd}')
" 2>/dev/null

