  // Cohezion cross-agent context injection (Story 12.7)
  try {
    const proc = Bun.spawn(
      ["./scripts/entire/entire-context.sh", "opencode"],
      { cwd: directory, stdout: "pipe", stderr: "ignore" }
    )
    const output = await new Response(proc.stdout).text()
    const context = JSON.parse(output)
    if (context.count > 0) {
      // Log context for OpenCode's system — it will appear in session logs
      console.log(`[cohezion] ${context.count} other active session(s)`)
    }
  } catch {
    // Fail-open: context injection failure must not crash OpenCode
  }
  break
}

