            self.metrics.success_without_guidance.append(success)
        else:
            self.metrics.executions_with_guidance += 1
            self.metrics.phi_with_guidance.append(actual_phi)
            self.metrics.coherence_with_guidance.append(actual_coherence)
            self.metrics.success_with_guidance.append(success)

    def get_metrics(self) -> GuidanceMetrics:
        return self.metrics


