from __future__ import annotations

import hashlib
import logging
from typing import TYPE_CHECKING, Any

import numpy as np

from .models import (
    ExecutionGuidance,
    GuidanceMetrics,
    GuidanceStrategy,
    TrajectoryHint,
)


if TYPE_CHECKING:
    from cohezion.core.persistence.surreal_client import SurrealClient

logger = logging.getLogger(__name__)


class ExperienceGuidance:
    """Experience-guided execution using SurrealDB journey data."""

    DIMENSION_WEIGHTS = np.array([0.08, 0.12, 0.10, 0.08, 0.10, 0.08, 0.15, 0.10, 0.08, 0.06, 0.03, 0.02])

    def __init__(
        self,
        surreal_client: SurrealClient | None = None,
        min_similarity: float = 0.6,
        max_journeys: int = 100,
        enable_metrics: bool = True,
    ):
        self.surreal_client = surreal_client
        self.min_similarity = min_similarity
        self.max_journeys = max_journeys
        self.enable_metrics = enable_metrics
        self.metrics = GuidanceMetrics()
        self._initialized = False

    async def initialize(self) -> bool:
        if self.surreal_client is None:
            self._initialized = True
            return True
        try:
            await self.surreal_client.connect()
            self._initialized = True
            return True
        except Exception as e:
            logger.warning("Failed to connect to SurrealDB: %s", e)
            self._initialized = True
            return False

    def get_guidance(
        self,
        task_description: str,
        operation_type: str,
        current_trajectory: np.ndarray | None = None,
        strategy: GuidanceStrategy = GuidanceStrategy.FULL,
        top_k: int = 5,
    ) -> ExecutionGuidance:
        if strategy == GuidanceStrategy.NONE:
            return ExecutionGuidance(strategy, [], None, [], 0.0, 0.5, [])

        similar = self._query_similar_journeys(task_description, operation_type, top_k * 2)
        if not similar:
            return ExecutionGuidance(strategy, [], None, [], 0.0, 0.5, ["No similar past executions found"])

        filtered = self._filter_by_similarity(similar, task_description)[:top_k]
        phi_scores = [j.get("phi_score", 0.5) for j in filtered]
        coherences = [j.get("coherence", 0.5) for j in filtered]

        expected_phi = float(np.mean(phi_scores)) if phi_scores else 0.5
        avg_coherence = float(np.mean(coherences)) if coherences else 0.5
        confidence = self._compute_confidence(filtered, avg_coherence)
        warnings = self._generate_warnings(filtered)

        optimal = None
        hints = []
        if strategy in (GuidanceStrategy.TRAJECTORY, GuidanceStrategy.FULL):
            optimal = self._compute_optimal_trajectory(filtered)
            hints = self._generate_trajectory_hints(optimal, filtered, confidence)

        return ExecutionGuidance(strategy, filtered, optimal, hints, confidence, expected_phi, warnings)

    def _query_similar_journeys(
        self, task_description: str, operation_type: str, limit: int = 10
    ) -> list[dict[str, Any]]:
        if self.surreal_client is None:
            return self._query_fallback(task_description, operation_type, limit)
        try:
            import asyncio

            query_embedding = self._embed_text(task_description)
            query = f"SELECT * FROM journey_record WHERE operation_type = '{operation_type}' ORDER BY vector::similarity::cosine(embedding, $embedding) DESC LIMIT {limit}"
            loop = asyncio.new_event_loop()
            try:
                asyncio.set_event_loop(loop)
                result = loop.run_until_complete(
                    self.surreal_client.query(query, {"embedding": query_embedding.tolist()})
                )
            finally:
                loop.close()
            if result and isinstance(result, list):
                return [self._normalize_journey(r) for r in result if isinstance(r, dict)]
        except Exception:
            pass
        return self._query_fallback(task_description, operation_type, limit)

    def _query_fallback(self, task_description: str, operation_type: str, limit: int) -> list[dict[str, Any]]:
        try:
            from cohezion.flume.experience_collector import ExperienceCollector

            experiences = ExperienceCollector().collect_all(max_samples=self.max_journeys)
            filtered = [exp for exp in experiences if exp.get("operation_type", "").lower() == operation_type.lower()]
            filtered.sort(key=lambda x: x.get("phi_score", 0.0), reverse=True)
            return filtered[:limit]
        except Exception:
            return []

    def _embed_text(self, text: str) -> np.ndarray:
        hash_obj = hashlib.sha256(text.encode())
        hash_bytes = hash_obj.digest()
        embedding = np.zeros(768, dtype=np.float32)
        for i in range(768):
            byte_idx = i % len(hash_bytes)
            phase = (2.0 * np.pi * i) / 768
            embedding[i] = (hash_bytes[byte_idx] / 255.0) * 0.5 + 0.25 * np.sin(phase) + 0.25 * np.cos(phase * 2)
        norm = np.linalg.norm(embedding)
        if norm > 0:
            embedding = embedding / norm
        return embedding

    def _normalize_journey(self, raw: dict[str, Any]) -> dict[str, Any]:
        trajectory = raw.get("trajectory_12d", [])
        return {
            "id": raw.get("id", ""),
            "task_description": raw.get("task_description", ""),
            "operation_type": raw.get("operation_type", ""),
            "trajectory": np.array(trajectory) if trajectory else np.zeros(12),
            "phi_score": float(raw.get("phi_score", 0.5)),
            "coherence": float(raw.get("coherence", 0.5)),
            "success": bool(raw.get("success", False)),
            "smoothness": float(raw.get("smoothness", 0.5)),
            "convergence": float(raw.get("convergence", 0.5)),
            "duration_seconds": float(raw.get("duration_seconds", 0.0)),
        }

    def _filter_by_similarity(self, journeys: list[dict[str, Any]], task_description: str) -> list[dict[str, Any]]:
        query_emb = self._embed_text(task_description)
        scored = []
        for journey in journeys:
            task_emb = self._embed_text(journey.get("task_description", ""))
            similarity = self._cosine_similarity(query_emb, task_emb)
            if similarity >= self.min_similarity:
                journey["_similarity"] = similarity
                scored.append((similarity, journey))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [j for _, j in scored]

    def _compute_optimal_trajectory(self, similar_journeys: list[dict[str, Any]]) -> np.ndarray:
        successful = [
            j for j in similar_journeys if j.get("success", False) and j.get("coherence", 0.0) >= 0.5
        ] or similar_journeys
        trajectories, weights = [], []
        for journey in successful:
            traj = journey.get("trajectory")
            if traj is None:
                continue
            traj_arr = np.asarray(traj, dtype=np.float32)
            if len(traj_arr) != 12:
                continue
            weight = journey.get("phi_score", 0.5) * 0.5 + journey.get("coherence", 0.5) * 0.5
            trajectories.append(traj_arr)
            weights.append(max(weight, 0.01))
        if not trajectories:
            return np.zeros(12)
        weights_arr = np.array(weights)
        weights_arr = weights_arr / weights_arr.sum()
        return np.clip(np.average(trajectories, axis=0, weights=weights_arr), 0.0, 1.0)

    def _generate_trajectory_hints(
        self, optimal_trajectory: np.ndarray, similar_journeys: list[dict[str, Any]], confidence: float
    ) -> list[TrajectoryHint]:
        hints = []
        trajectories = [
            np.asarray(j.get("trajectory", []), dtype=np.float32)
            for j in similar_journeys
            if j.get("trajectory") is not None
        ]
        if trajectories:
            variances = np.var(np.array(trajectories), axis=0)
            for dim in range(12):
                if variances[dim] > 0.1:
                    best_journey = max(similar_journeys, key=lambda j: j.get("phi_score", 0.0), default={})
                    hints.append(
                        TrajectoryHint(
                            dim,
                            float(optimal_trajectory[dim]),
                            float(confidence * (1.0 - variances[dim])),
                            best_journey.get("id", "unknown"),
                            f"Based on {len(similar_journeys)} similar executions.",
                        )
                    )
        return hints

    def _generate_warnings(self, journeys: list[dict[str, Any]]) -> list[str]:
        warnings = []
        failed = [j for j in journeys if not j.get("success", True)]
        if len(failed) >= 2:
            warnings.append(f"{len(failed)} similar tasks failed. Review approach carefully.")
        low_coherence = [j for j in journeys if j.get("coherence", 1.0) < 0.4]
        if low_coherence:
            warnings.append(
                f"Low coherence trend ({np.mean([j.get('coherence', 0.0) for j in low_coherence]):.2f}) in similar tasks."
            )
        return warnings

    def _compute_confidence(self, similar_journeys: list[dict[str, Any]], avg_coherence: float) -> float:
        if not similar_journeys:
            return 0.0
        successes = [j.get("success", False) for j in similar_journeys]
        consistency = 1.0 - abs(sum(successes) / len(successes) - 0.5) * 2 if successes else 0.5
        return float(
            np.clip(min(len(similar_journeys) / 5, 1.0) * 0.3 + avg_coherence * 0.5 + consistency * 0.2, 0.0, 1.0)
        )

    def _cosine_similarity(self, a: np.ndarray, b: np.ndarray) -> float:
        dot, na, nb = np.dot(a, b), np.linalg.norm(a), np.linalg.norm(b)
        return float(dot / (na * nb)) if na > 0 and nb > 0 else 0.0

    def record_outcome(
        self,
        task_description: str,
        operation_type: str,
        guidance: ExecutionGuidance,
        actual_phi: float,
        actual_coherence: float,
        success: bool,
    ) -> None:
        if not self.enable_metrics:
            return
        if guidance.strategy == GuidanceStrategy.NONE:
            self.metrics.executions_without_guidance += 1
            self.metrics.phi_without_guidance.append(actual_phi)
            self.metrics.coherence_without_guidance.append(actual_coherence)
            self.metrics.success_without_guidance.append(success)
        else:
            self.metrics.executions_with_guidance += 1
            self.metrics.phi_with_guidance.append(actual_phi)
            self.metrics.coherence_with_guidance.append(actual_coherence)
            self.metrics.success_with_guidance.append(success)

    def get_metrics(self) -> GuidanceMetrics:
        return self.metrics


def create_experience_guidance(surreal_client=None, surreal_url=None, **kwargs):
    """Factory for ExperienceGuidance.

    Args:
        surreal_client: Pre-built SurrealDB client.
        surreal_url: SurrealDB URL (consumed here, not forwarded).
    """
    return ExperienceGuidance(surreal_client=surreal_client, **kwargs)

