@dataclass
class CompressionStats:
    """Statistics for compression operations."""

    total_compressed: int = 0
    total_decompressed: int = 0
    bytes_original: int = 0
    bytes_compressed: int = 0
    bytes_saved: int = 0
    compression_failures: int = 0
    decompression_failures: int = 0
    skipped_small: int = 0
    skipped_ratio: int = 0

    @property
    def compression_ratio(self) -> float:
        """Overall compression ratio (compressed/original)."""
        if self.bytes_original == 0:
            return 1.0
        return self.bytes_compressed / self.bytes_original

    @property
    def space_savings_percent(self) -> float:
        """Space savings percentage."""
        if self.bytes_original == 0:
            return 0.0
        return (1.0 - self.compression_ratio) * 100

    @property
    def avg_original_size(self) -> float:
        """Average original size of compressed values."""
        if self.total_compressed == 0:
            return 0.0
        return self.bytes_original / self.total_compressed

    @property
    def avg_compressed_size(self) -> float:
        """Average compressed size."""
        if self.total_compressed == 0:
            return 0.0
        return self.bytes_compressed / self.total_compressed

    def to_dict(self) -> dict[str, Any]:
        """Convert stats to dictionary."""
        return {
            "total_compressed": self.total_compressed,
            "total_decompressed": self.total_decompressed,
            "bytes_original": self.bytes_original,
            "bytes_compressed": self.bytes_compressed,
            "bytes_saved": self.bytes_saved,
            "compression_failures": self.compression_failures,
            "decompression_failures": self.decompression_failures,
            "skipped_small": self.skipped_small,
            "skipped_ratio": self.skipped_ratio,
            "compression_ratio": round(self.compression_ratio, 4),
            "space_savings_percent": round(self.space_savings_percent, 2),
            "avg_original_size": round(self.avg_original_size, 2),
            "avg_compressed_size": round(self.avg_compressed_size, 2),
        }


